import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        final long MOD = 1000000007;
        long result = 1;
        long[] visited = new long[(int) p + 1];
        long[] frequency = new long[(int) p + 1];

        // Define the explore function
        class Explorer {
            void explore(int n, int length) {
                if (visited[n] == 1) {
                    frequency[length]++;
                    return;
                }
                visited[n] = 1;
                long nextN = ((long) n * k) % p;
                explore((int) nextN, length + 1);
            }
        }

        Explorer explorer = new Explorer();

        if (k != 0 && k != 1) {
            for (int i = 1; i < p; i++) {
                if (visited[i] == 0) {
                    explorer.explore(i, 0);
                }
            }
            for (int i = 1; i <= p; i++) {
                for (long j = 1; j <= frequency[i]; j++) {
                    result = (result * ((frequency[i] * i) + 1)) % MOD;
                }
            }
        } else if (k == 0) {
            for (int i = 1; i < p; i++) {
                result = (result * p) % MOD;
            }
        } else if (k == 1) {
            for (int i = 1; i <= p; i++) {
                result = (result * p) % MOD;
            }
        }

        System.out.println(result);
        sc.close();
    }
}

